<?php
declare(strict_types=1);
namespace KodVadAll\Modules\POS;
use PDO;
use RuntimeException;
use Throwable;
use KodVadAll\Core\NotificationService;
use KodVadAll\Core\WebhookService;
final class POSController
{
 public static function handle(PDO $db,array $admin):void
 {
  kd_require_permission('pos.view');
  if($_SERVER['REQUEST_METHOD']==='POST'){kd_csrf_check();kd_require_permission('pos.use');$action=(string)($_POST['form_action']??'');try{
   if($action==='open_shift'){$cash=max(0,(float)($_POST['opening_cash']??0));$q=$db->prepare("SELECT id FROM pos_shifts WHERE user_id=? AND status='open' LIMIT 1");$q->execute([(int)$admin['id']]);if($q->fetchColumn())throw new RuntimeException('Açık kasanız zaten var.');$db->prepare("INSERT INTO pos_shifts (user_id,opening_cash,status,opened_at) VALUES (?,?,'open',NOW())")->execute([(int)$admin['id'],$cash]);kd_audit('pos.shift_opened','pos_shift',(int)$db->lastInsertId());}
   if($action==='cash_movement'){$shift=self::openShift($db,(int)$admin['id']);$direction=(string)($_POST['direction']??'');$amount=(float)($_POST['amount']??0);$reason=trim((string)($_POST['reason']??''));if(!in_array($direction,['in','out'],true)||$amount<=0||$reason==='')throw new RuntimeException('Kasa hareketi bilgileri geçersiz.');$db->prepare('INSERT INTO pos_cash_movements (shift_id,user_id,direction,amount,reason,created_at) VALUES (?,?,?,?,?,NOW())')->execute([(int)$shift['id'],(int)$admin['id'],$direction,$amount,$reason]);}
   if($action==='close_shift'){$shift=self::openShift($db,(int)$admin['id']);$expected=self::expectedCash($db,(int)$shift['id']);$closing=(float)($_POST['closing_cash']??-1);if($closing<0)throw new RuntimeException('Kapanış kasa tutarı geçersiz.');$db->prepare("UPDATE pos_shifts SET closing_cash=?,expected_cash=?,cash_difference=?,status='closed',closed_at=NOW() WHERE id=?")->execute([$closing,$expected,$closing-$expected,(int)$shift['id']]);kd_audit('pos.shift_closed','pos_shift',(int)$shift['id']);}
   header('Location: index.php?page=pos',true,303);exit;
  }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Kasa işlemi tamamlanamadı.';}}
  $q=$db->prepare("SELECT * FROM pos_shifts WHERE user_id=? AND status='open' ORDER BY id DESC LIMIT 1");$q->execute([(int)$admin['id']]);$shift=$q->fetch()?:null;$recent=$db->query("SELECT id,order_number,grand_total,payment_method,created_at FROM orders WHERE order_source='pos' ORDER BY id DESC LIMIT 10")->fetchAll();$pageTitle='Hızlı Satış / POS';ob_start();require KD_ROOT.'/app/Views/pos/index.php';$content=ob_get_clean();require KD_ROOT.'/app/Views/layouts/admin.php';
 }
 public static function api(PDO $db,array $admin):void
 {
  kd_require_permission('pos.use');header('Content-Type: application/json; charset=utf-8');$action=(string)($_GET['action']??$_POST['action']??'');
  if($action==='search'&&$_SERVER['REQUEST_METHOD']==='GET'){$term=trim((string)($_GET['q']??''));if($term===''){echo json_encode(['success'=>true,'data'=>[]]);return;}$q=$db->prepare("SELECT id,name,sku,barcode,sale_price,tax_rate,stock_quantity,track_stock FROM products WHERE status='active' AND (barcode=? OR sku=? OR name LIKE ?) ORDER BY (barcode=?) DESC LIMIT 15");$like='%'.$term.'%';$q->execute([$term,$term,$like,$term]);echo json_encode(['success'=>true,'data'=>$q->fetchAll()],JSON_UNESCAPED_UNICODE);return;}
  if($action==='sale'&&$_SERVER['REQUEST_METHOD']==='POST'){kd_csrf_check();try{$cart=json_decode((string)($_POST['cart_json']??''),true);$method=(string)($_POST['payment_method']??'cash');if(!in_array($method,['cash','card'],true)||!is_array($cart)||!$cart||count($cart)>60)throw new RuntimeException('Satış sepeti veya ödeme yöntemi geçersiz.');$db->beginTransaction();$shift=self::openShift($db,(int)$admin['id'],true);$defaultWarehouseId=(int)$db->query("SELECT id FROM warehouses WHERE is_default=1 AND status='active' LIMIT 1")->fetchColumn();if($defaultWarehouseId<1)throw new RuntimeException('Varsayılan depo bulunamadı.');$items=[];$subtotal=0;$taxTotal=0;
   foreach($cart as $line){$productId=(int)($line['product_id']??0);$qty=(float)($line['quantity']??0);if($qty<=0||$qty>100000)throw new RuntimeException('Ürün miktarı geçersiz.');$q=$db->prepare("SELECT * FROM products WHERE id=? AND status='active' FOR UPDATE");$q->execute([$productId]);$product=$q->fetch();if(!$product)throw new RuntimeException('Ürün bulunamadı.');if((int)$product['track_stock']){$ws=$db->prepare('SELECT quantity FROM product_warehouse_stocks WHERE product_id=? AND warehouse_id=? FOR UPDATE');$ws->execute([$productId,$defaultWarehouseId]);$warehouseStock=$ws->fetch();if(!$warehouseStock||(float)$warehouseStock['quantity']<$qty)throw new RuntimeException('Varsayılan depoda yetersiz stok: '.$product['name']);}$lineSub=round($qty*(float)$product['sale_price'],2);$lineTax=round($lineSub*(float)$product['tax_rate']/100,2);$items[]=[$product,$qty,$lineSub,$lineTax];$subtotal+=$lineSub;$taxTotal+=$lineTax;}
   $customerId=(int)($_POST['customer_id']??0);if($customerId<1){$q=$db->prepare("SELECT id FROM customers WHERE customer_code='POS-WALKIN' LIMIT 1");$q->execute();$customerId=(int)$q->fetchColumn();if(!$customerId){$db->prepare("INSERT INTO customers (customer_code,type,name,status,created_at) VALUES ('POS-WALKIN','individual','Perakende Müşteri','active',NOW())")->execute();$customerId=(int)$db->lastInsertId();}}
   $total=round($subtotal+$taxTotal,2);$temp='TMP-POS-'.bin2hex(random_bytes(5));$db->prepare("INSERT INTO orders (order_number,customer_id,status,subtotal,tax_total,discount_total,grand_total,coupon_code,order_source,payment_method,payment_status,currency,notes,pos_shift_id,stock_deducted_at,created_at) VALUES (?,?,'confirmed',?,?,0,?,NULL,'pos',?,'paid','TRY','POS satışı',?,NOW(),NOW())")->execute([$temp,$customerId,$subtotal,$taxTotal,$total,$method,(int)$shift['id']]);$orderId=(int)$db->lastInsertId();$number='POS-'.date('Y').'-'.str_pad((string)$orderId,7,'0',STR_PAD_LEFT);$db->prepare('UPDATE orders SET order_number=? WHERE id=?')->execute([$number,$orderId]);$itemInsert=$db->prepare('INSERT INTO order_items (order_id,product_id,product_name,sku,quantity,unit_price,tax_rate,line_subtotal,line_tax,line_total,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,NOW())');
   foreach($items as [$product,$qty,$lineSub,$lineTax]){$itemInsert->execute([$orderId,$product['id'],$product['name'],$product['sku'],$qty,$product['sale_price'],$product['tax_rate'],$lineSub,$lineTax,$lineSub+$lineTax]);if((int)$product['track_stock']){$pid=(int)$product['id'];$ws=$db->prepare('SELECT quantity FROM product_warehouse_stocks WHERE product_id=? AND warehouse_id=? FOR UPDATE');$ws->execute([$pid,$defaultWarehouseId]);$warehouseStock=$ws->fetch();$before=$warehouseStock?(float)$warehouseStock['quantity']:0.0;$after=$before-$qty;if($after<0)throw new RuntimeException('Varsayılan depoda yetersiz stok: '.$product['name']);$db->prepare('UPDATE product_warehouse_stocks SET quantity=?,updated_at=NOW() WHERE product_id=? AND warehouse_id=?')->execute([$after,$pid,$defaultWarehouseId]);$total=(float)$db->query('SELECT COALESCE(SUM(quantity),0) FROM product_warehouse_stocks WHERE product_id='.$pid)->fetchColumn();$db->prepare('UPDATE products SET stock_quantity=?,updated_at=NOW() WHERE id=?')->execute([$total,$pid]);$db->prepare("INSERT INTO product_stock_movements(product_id,warehouse_id,user_id,movement_type,quantity,before_quantity,after_quantity,note,reference_type,reference_id,created_at) VALUES(?,?,?,'out',?,?,?,?, 'order',?,NOW())")->execute([$pid,$defaultWarehouseId,(int)$admin['id'],$qty,$before,$after,'POS satış '.$number,$orderId]);}}
   $db->prepare('INSERT INTO order_status_history (order_id,user_id,from_status,to_status,note,created_at) VALUES (?,?,NULL,?,?,NOW())')->execute([$orderId,(int)$admin['id'],'confirmed','POS hızlı satış']);$db->prepare("INSERT INTO payment_transactions (order_id,provider,provider_reference,amount,currency,status,created_at) VALUES (?,? ,?,?,'TRY','paid',NOW())")->execute([$orderId,'pos','POS'.$orderId,$total]);$db->commit();kd_audit('pos.sale_created','order',$orderId);NotificationService::notifyRoles($db,['owner','admin','manager'],'POS satışı tamamlandı',$number.' · '.number_format($total,2,',','.').' TL','index.php?page=orders&action=view&id='.$orderId,'success');WebhookService::enqueue($db,'order.created',['id'=>$orderId,'order_number'=>$number,'status'=>'confirmed','grand_total'=>$total,'source'=>'pos']);echo json_encode(['success'=>true,'data'=>['id'=>$orderId,'order_number'=>$number,'total'=>$total,'payment_method'=>$method]],JSON_UNESCAPED_UNICODE);return;
  }catch(Throwable $e){if($db->inTransaction())$db->rollBack();http_response_code($e instanceof RuntimeException?422:500);echo json_encode(['success'=>false,'error'=>$e instanceof RuntimeException?$e->getMessage():'Satış kaydedilemedi.'],JSON_UNESCAPED_UNICODE);return;}}
  http_response_code(404);echo json_encode(['success'=>false,'error'=>'İşlem bulunamadı.']);
 }
 private static function openShift(PDO $db,int $userId,bool $lock=false):array
 {
  $q=$db->prepare("SELECT * FROM pos_shifts WHERE user_id=? AND status='open' ORDER BY id DESC LIMIT 1".($lock?' FOR UPDATE':''));$q->execute([$userId]);$shift=$q->fetch();if(!$shift)throw new RuntimeException('Satış yapmadan önce kasayı açın.');return $shift;
 }
 private static function expectedCash(PDO $db,int $shiftId):float
 {
  $q=$db->prepare("SELECT s.opening_cash + COALESCE((SELECT SUM(o.grand_total) FROM orders o WHERE o.pos_shift_id=s.id AND o.payment_method='cash' AND o.payment_status='paid'),0) + COALESCE((SELECT SUM(m.amount) FROM pos_cash_movements m WHERE m.shift_id=s.id AND m.direction='in'),0) - COALESCE((SELECT SUM(m.amount) FROM pos_cash_movements m WHERE m.shift_id=s.id AND m.direction='out'),0) FROM pos_shifts s WHERE s.id=?");$q->execute([$shiftId]);return (float)$q->fetchColumn();
 }
}
